"""engine/stock_manifest.json is GENERATED by tools/gen_stock_manifest.py."""
import json

import pytest

from engine import paths
from tests.helpers.bc_assets import require_game_dir
from tools import gen_stock_manifest as g


def _committed():
    return json.loads(g.manifest_path().read_text(encoding="utf-8"))["modules"]


def _built():
    require_game_dir("scripts")
    return g.build(paths.stock_scripts(), paths.PROJECT_ROOT)


def test_committed_manifest_matches_the_configured_install():
    committed = _committed()
    built = _built()
    unknown = sorted(p for p, hs in built.items()
                     if not set(hs) <= set(committed.get(p, [])))
    if unknown:
        pytest.skip("a retail build this manifest does not know: "
                    + ", ".join(unknown[:10]))
    assert set(built) == set(committed)
    assert g.manifest_path().read_text(encoding="utf-8") == g.serialise(committed)


def test_manifest_lists_1201_minus_the_root_shims():
    built = _built()
    scripts = paths.stock_scripts()
    total = sum(1 for _ in scripts.rglob("*.pyc"))
    if total != 1201:
        pytest.skip("not the known 1,201-file retail install")
    excluded = total - len(built)
    assert excluded == len([p for p in scripts.rglob("*.pyc")
                            if (paths.PROJECT_ROOT
                                / (p.relative_to(scripts).with_suffix("").as_posix()
                                   + ".py")).exists()])
    assert len(_committed()) == 1201 - excluded
